def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            stack.pop()
            current_group += char

        if char != "(" and char != ")":
            current_group += char

        if not stack:
            yield current_group
            current_group = ""

    if current_group:
        yield current_group

    if stack:
        raise ValueError("Unbalanced parenthesis")

