def polynomial_to_string(n, coeffs):
    result = []
    for i in range(len(coeffs)):
        coeff = coeffs[-(i + 1)]
        if coeff == 0:
            continue
        term = ""
        if coeff < 0:
            term = "-"
        elif coeff > 1:
            term = "+"
        if coeff != 1 or i == 0:
            term += str(abs(coeff))
        if i != 0:
            term += "x^" + str(n - i)
        result.append(term)
    return "".join(result)

