def count_sequences(n, last, memo):
    if n < 0:
        return 0
    if n == 0:
        return 1
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, int(n+1)):
        if i <= last//2:
            count += count_sequences(n-i, i, memo)
    memo[last] = count
    return count

