def is_prime(num):
    # Handle edge cases for numbers less than or equal to 1 and small numbers
    if num <= 1 or num in [2, 3]:
        return True

    # Check for divisibility by 2 and 3
    if num % 2 == 0 or num % 3 == 0:
        return False

    # Test for factors up to the square root of the number using a 6k +/- 1 optimization
    for i in range(5, int(num ** 0.5) + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False

    # If no factors were found, the number is prime
    return True

